const t="catalog-demo-cart";let e=function(){try{const e=localStorage.getItem(t);return e?JSON.parse(e):{}}catch(t){return{}}}();const r=new Set;function n(){!function(e){try{localStorage.setItem(t,JSON.stringify(e))}catch(t){}}(e),r.forEach(t=>t(e))}export function subscribe(t){return r.add(t),()=>r.delete(t)}export function getCart(){return{...e}}export function addToCart(t,r=1){e[t]=(e[t]||0)+r,n()}export function setQuantity(t,r){r<=0?delete e[t]:e[t]=r,n()}export function removeFromCart(t){delete e[t],n()}export function clearCart(){e={},n()}export function getItemCount(){return Object.values(e).reduce((t,e)=>t+e,0)}